<?php
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();foreach(['company_name','company_email','currency'] as $k){$pdo->prepare('INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE `value`=VALUES(`value`)')->execute([$k,$_POST[$k]??'']);}flash('success','Configurações atualizadas.');redirect('?module=configuracoes');
}
$rows=$pdo->query('SELECT * FROM settings')->fetchAll();$settings=[];foreach($rows as $r)$settings[$r['key']]=$r['value'];
?>
